        OON.MARKERS[marker.id] = OON.MARKERS[marker.id] or {}
        OON.MARKERS[marker.id].room = OON.MARKERS[marker.id].room or "imported"
        OON.MARKERS[marker.id].kind = OON.MARKERS[marker.id].kind or "m0r_route"
        OON.MARKERS[marker.id].label = marker.label
        OON.MARKERS[marker.id].renderLabel = tostring(marker.sourceIndex)
        OON.MARKERS[marker.id].x = marker.x
        OON.MARKERS[marker.id].y = marker.y
        OON.MARKERS[marker.id].z = marker.z
        OON.MARKERS[marker.id].source = profile.profileName .. "#" .. tostring(marker.sourceIndex)
    end
end
